package dev.eugheist.ttmodern;
import dev.eugheist.tc4modern.*;
import net.minecraft.world.item.*;
import thaumcraft.api.aspects.*;
final class XPDrainFocusAudit {
 static void check(boolean ok,String label){if(!ok)throw new IllegalStateException("TT XP drain: "+label);}
 static void run(net.minecraft.server.MinecraftServer server){var player=new net.neoforged.neoforge.common.util.FakePlayer(server.overworld(),new com.mojang.authlib.GameProfile(java.util.UUID.randomUUID(),"XPDrainAudit"));var focus=XPDrainFocus.ITEM.get();var wand=new ItemStack(WandParts.WAND.get());var aspects=Aspect.getPrimalAspects();player.giveExperiencePoints(1000);for(int i=0;i<6;i++)focus.onUsingFocusTick(wand,player,0);check(player.totalExperience==910&&aspects.stream().allMatch(a->WandData.get(wand,a)==500),"six ticks rotate all primals,5vis each,exact90XP: XP="+player.totalExperience+",capacity="+WandData.capacity(wand)+",vis="+aspects.stream().map(a->a.getTag()+"="+WandData.get(wand,a)).toList());for(var a:aspects)WandData.add(wand,a,100000,true);int before=player.totalExperience;focus.onUsingFocusTick(wand,player,0);check(player.totalExperience==before,"full wand consumes no XP");var almost=new ItemStack(WandParts.WAND.get());for(var a:aspects)net.minecraft.world.item.component.CustomData.update(net.minecraft.core.component.DataComponents.CUSTOM_DATA,almost,t->thaumcraft.common.lib.vis.VisStorage.addRealVis(t,a,WandData.capacity(almost)-(a==aspects.getFirst()?10:0),true,WandData.capacity(almost)));focus.onUsingFocusTick(almost,player,0);check(player.totalExperience==before-15&&WandData.get(almost,aspects.getFirst())==WandData.capacity(almost),"skip five full aspects,clamp final10centivis and charge15XP");var empty=new ItemStack(WandParts.WAND.get());player.giveExperiencePoints(-player.totalExperience+14);focus.onUsingFocusTick(empty,player,0);check(player.totalExperience==14&&aspects.stream().allMatch(a->WandData.get(empty,a)==0),"insufficient14XP consumes and charges nothing");player.giveExperiencePoints(1);focus.onUsingFocusTick(empty,player,0);check(player.totalExperience==0&&aspects.stream().mapToInt(a->WandData.get(empty,a)).sum()==500&&player.experienceLevel==0&&player.experienceProgress==0,"exact15XP crosses level boundary without negative level/progress");var stack=new ItemStack(focus);check(stack.getRarity()==Rarity.EPIC&&focus.isVisCostPerTick(stack)&&focus.getVisCost(stack).size()==0&&focus.getPossibleUpgradesByRank(stack,1).length==0,"original EPIC/per-tick/emptyvis/no-upgrades");var recipe=InfusionItemRecipes.all().stream().filter(r->r.key().equals("FOCUS_XP_DRAIN")).findFirst().orElseThrow();check(recipe.componentStacks().size()==6&&recipe.componentStacks().get(1).is(Items.EXPERIENCE_BOTTLE)&&recipe.componentStacks().get(3).is(ThaumicTinkererModern.XP_TALISMAN.get())&&recipe.componentStacks().get(4).is(Items.ENCHANTING_TABLE),"original six infusion components");System.out.println("TT XP DRAIN AUDIT: ALL PASS (six primals/rotation,15XP buys5vis,full/insufficient refusal,capacity clamp,modern level boundary,EPIC/no upgrades,recipe)");}
}
